insert into public.iq_questions
  (topic, track, level, scenario, question, choices, correct_index, explanation, difficulty, diagram, playbook_ref)
values
  ('general', 'defense', 1, 'Nobody on, one out. The batter drops a bunt toward the pitcher. You''re the second baseman.', 'Where do you go?', array['Cover second base', 'Cover first base', 'Charge in toward the bunt', 'Back up the pitcher'], 1, 'The first baseman charges the bunt, so first base is empty. You slide over to cover first and take the throw while the shortstop takes second.', 1, '{"runners":[],"outs":1,"you":"2B","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.3 · No runners, <2 outs: bunt coverage at 1B'),
  ('general', 'defense', 1, 'Nobody on, nobody out. The batter bunts down the third-base side, and both you and the pitcher can get to it. You''re the third baseman.', 'Who should field it?', array['You, the third baseman', 'The pitcher', 'The catcher', 'The shortstop'], 0, 'When a corner can reach a bunt, she takes it away from the pitcher. The third baseman is the best choice because she''s already moving toward first as she picks it up. Call for it loudly.', 1, '{"runners":[],"outs":0,"you":"3B","ball":{"at":"bunt-3B","type":"bunt"}}'::jsonb, 'Defensive Playbook p.3 · No runners, <2 outs: who fields the bunt'),
  ('general', 'defense', 1, 'Nobody on, one out. Routine ground ball to the shortstop, who throws to first. You''re the catcher.', 'What''s your job on this play?', array['Stay at home plate', 'Cover third base', 'Trail the batter toward first, staying in foul ground', 'Walk out toward the mound'], 2, 'With nobody on there''s no play at the plate, so you follow the batter toward first, staying in foul ground. If the throw gets past the first baseman, you''re there to stop the batter from taking an extra base.', 1, '{"runners":[],"outs":1,"you":"C","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Defensive Playbook p.6 · No runners, <2 outs: catcher backup on a ground ball'),
  ('general', 'defense', 1, 'Nobody on, nobody out. A ground ball gets through the left side into left field for a single. You''re the left fielder.', 'Where do you throw?', array['First base', 'Third base', 'Home plate', 'Second base'], 3, 'The only runner is the batter. Get the ball to second, using the shortstop as your cut, so she can''t stretch the hit into a double.', 1, '{"runners":[],"outs":0,"you":"LF","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.7 · No runners, <2 outs: ground-ball single to left'),
  ('general', 'defense', 1, 'Runner on second, nobody out. Fly ball to left field, and the runner is tagging up to try for third. You''re the shortstop going out to be the cut.', 'Where do you line up?', array['Between the left fielder and second base', 'Between the left fielder and home plate', 'Between the left fielder and third base', 'On top of third base'], 2, 'The throw is headed to third to stop the tag-up, so the cut sets up in a straight line between the left fielder and third base. Peek at the bag to check your line, and listen for teammates telling you to shift left or right.', 1, '{"runners":["second"],"outs":0,"you":"SS","ball":{"at":"LF","type":"fly"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.27 · Runner at 2B, <2 outs: lining up as the cut on a fly to left'),
  ('general', 'defense', 1, 'Runner on first, nobody out. A hard ground ball comes right back to you on the mound.', 'Where do you throw?', array['First base', 'Second base', 'Third base', 'Nowhere yet, look the runner back first'], 1, 'A hard-hit ball gives you time to get the lead runner at second, and the shortstop may be able to turn two. On a slow roller you''d take the sure out at first instead.', 1, '{"runners":["first"],"outs":0,"you":"P","ball":{"at":"P","type":"ground"}}'::jsonb, 'Defensive Playbook p.13 · Runner at 1B, <2 outs: hard comebacker to the pitcher'),
  ('general', 'defense', 1, 'Runner on first, one out. Hard grounder to the shortstop, who throws to you covering second. You''re the second baseman.', 'What do you need to do to get the runner coming from first?', array['Catch it and tag the runner as she slides in', 'Catch it and throw to first without touching the base', 'Catch it and chase the runner back toward first', 'Catch it and touch second base'], 3, 'Because the batter is running, the runner from first is forced to second. On a force out you only need the ball and a foot on the bag, and then you can turn and throw to first for the double play.', 1, '{"runners":["first"],"outs":1,"you":"2B","ball":{"at":"SS","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.15 · Runner at 1B, <2 outs: force out at second'),
  ('general', 'defense', 1, 'Nobody on, one out. The batter hits a ground-ball single to left and heads for first. You''re the first baseman covering the bag, and you don''t have the ball.', 'If you''re standing in her path and she has to run around you, what can the umpire call?', array['Obstruction on you', 'Interference on the runner', 'Nothing, the base belongs to the fielder', 'An automatic out on the runner'], 0, 'Obstruction is a defensive player without the ball getting in a runner''s way. Cover the base, but leave the runner a clear path to and around it.', 1, '{"runners":[],"outs":1,"you":"1B","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.2 · No runners, <2 outs: obstruction at first base'),
  ('general', 'defense', 1, 'Nobody on, two outs. A hard ground ball comes straight at you in right field.', 'Where do you throw?', array['Through the cut to second base', 'Third base', 'First base', 'Run it back in to the infield'], 2, 'A ball hit hard right at you gives you a shot at throwing the batter out at first, which ends the inning with two outs. On a normal single you''d throw through the cut to second instead.', 1, '{"runners":[],"outs":2,"you":"RF","ball":{"at":"RF","type":"ground"}}'::jsonb, 'Defensive Playbook p.73 · No runners, 2 outs: hard grounder right at the right fielder'),
  ('general', 'defense', 1, 'Runner on first, two outs. A ground ball single goes into left field, and the runner is running hard. You''re the left fielder.', 'Where does your throw go?', array['Through the cut to third base', 'Through the cut to second base', 'First base', 'Home plate'], 0, 'With two outs the runner on first is going on contact and will try to go first to third. Throw through the shortstop cut to third to keep her from getting there.', 1, '{"runners":["first"],"outs":2,"you":"LF","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.77 · Runner at 1B, 2 outs: ground-ball single to left'),
  ('general', 'defense', 2, 'Runner on second, one out. Ground ball to you at shortstop.', 'What''s your play?', array['Throw to third right away to get the lead runner', 'Look the runner back to second, then throw to first', 'Throw to first without looking at the runner', 'Run the ball over to second base'], 1, 'The runner at second isn''t forced, so a throw to third would need a tag. Freeze her with a look, then take the out at first; if she commits toward third, go after her instead.', 2, '{"runners":["second"],"outs":1,"you":"SS","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Defensive Playbook p.23 · Runner at 2B, <2 outs: check the runner before throwing to 1B'),
  ('general', 'defense', 2, 'Runner on second, nobody out. The batter bunts to the pitcher. The shortstop runs to cover third and the second baseman covers first. You''re the center fielder.', 'What''s your job?', array['Back up third base', 'Back up first base', 'Stay deep in center', 'Run in and cover second base'], 3, 'With the shortstop at third and the second baseman at first, no infielder is left for second. The center fielder runs in and takes the bag, while the left and right fielders back up third and first.', 2, '{"runners":["second"],"outs":0,"you":"CF","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.20 · Runner at 2B, <2 outs: who covers second on a bunt'),
  ('general', 'defense', 2, 'Runner on first, one out. A hard grounder is hit to the first baseman right next to the bag. She steps on first for the out, then throws to you covering second. You''re the shortstop.', 'What do you have to do to get the runner from first?', array['Touch second base', 'Tag the runner', 'Throw back to first base', 'Nothing, she''s already out'], 1, 'Once the batter is out at first, the runner from first is no longer forced, so the force at second is gone. Now it''s a tag play, and the first baseman should tell you that.', 2, '{"runners":["first"],"outs":1,"you":"SS","ball":{"at":"1B","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.14 · Runner at 1B, <2 outs: force removed after the out at first'),
  ('general', 'defense', 2, 'Runner on first, one out. A ground ball splits the right-center gap, and the second baseman races out to be the first cut. You''re the first baseman.', 'What''s your job?', array['Stay on first base', 'Cover second base', 'Set up as a second cut lined up toward home', 'Back up home plate'], 2, 'On a gap ball the runner from first may try to score, so the throw may need two relays. You become the second (double) cut in line with home, the catcher stays at the plate, and the pitcher backs her up.', 2, '{"runners":["first"],"outs":1,"you":"1B","ball":{"at":"RCF-gap","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.18 · Runner at 1B, <2 outs: double cut on a gap ball'),
  ('general', 'defense', 2, 'Runner on third, one out. A slow ground ball is hit to you at first base, a few steps in front of the bag.', 'What''s the best play?', array['Move toward the batter-runner and tag her, keeping the runner at third in sight', 'Turn and run to first base to step on it', 'Throw home right away', 'Throw to second base'], 0, 'Going toward the batter to tag her keeps the runner at third in front of you. If you turn your back to run to the bag, she can break for home without you seeing it.', 2, '{"runners":["third"],"outs":1,"you":"1B","ball":{"at":"1B","type":"ground"}}'::jsonb, 'Defensive Playbook p.31 · Runner at 3B, <2 outs: slow roller to the first baseman'),
  ('general', 'defense', 2, 'Runner on second, two outs. Routine ground ball to you at shortstop, and the runner is running on contact.', 'Where do you throw?', array['Third base to tag the runner', 'Home plate', 'First base', 'Second base'], 2, 'With two outs, the out at first ends the inning and the runner''s advance doesn''t matter. Don''t trade an easy out at first for a hard tag play at third.', 2, '{"runners":["second"],"outs":2,"you":"SS","ball":{"at":"SS","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.80 · Runner at 2B, 2 outs: take the out at first'),
  ('general', 'defense', 2, 'Runner on third, two outs. The batter bunts toward you at third, and the runner breaks for home.', 'Where do you throw?', array['Home plate to stop the run', 'Second base', 'Hold the ball', 'First base'], 3, 'With two outs, getting the batter at first ends the inning, and the run can''t count when the third out is the batter retired before she reaches first. The catcher stays home and calls for the throw to first.', 2, '{"runners":["third"],"outs":2,"you":"3B","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.83 · Runner at 3B, 2 outs: bunt to the third baseman'),
  ('general', 'defense', 2, 'Runner on second, one out. The runner wanders too far off the bag and gets caught between second and third. You''re the third baseman with the ball, and the shortstop is at second.', 'How should you and the shortstop line up so you can throw back and forth?', array['Both on the same side of the base path', 'Directly on the base line with the runner between you', 'On opposite sides of the base path', 'It doesn''t matter as long as you throw hard'], 0, 'If the runner is directly between you, a throw can hit her. Both fielders step to the same side of the base path so the ball has a clear lane.', 2, '{"runners":["second"],"outs":1,"you":"3B","arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.2 · Runner at 2B, <2 outs: rundown throwing lane'),
  ('general', 'defense', 2, 'Runner on first, two outs. Ground ball to you at second base, and the runner from first runs into you while you''re fielding it.', 'What''s the call?', array['Obstruction on you', 'No call, the base path belongs to the runner', 'No pitch, everyone goes back', 'Interference on the runner'], 3, 'A fielder making a play on a batted ball has the right to that spot. When a runner runs into her, that''s interference on the offense, so you don''t have to get out of her way to field the ball.', 2, '{"runners":["first"],"outs":2,"you":"2B","ball":{"at":"2B","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.2 · Runner at 1B, 2 outs: interference on a ground ball to 2B'),
  ('general', 'defense', 2, 'Runner on first, nobody out. A soft bunt dies on the grass and you have to charge hard to get it. You''re the third baseman.', 'Where do you throw?', array['Second base to get the lead runner', 'First base', 'Hold the ball', 'Home plate'], 1, 'On a slow bunt there''s usually no time to beat the lead runner to second, so take the sure out at first, where the second baseman is covering. On a hard bunt you''d look to get the lead runner instead.', 2, '{"runners":["first"],"outs":0,"you":"3B","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.13 · Runner at 1B, <2 outs: slow bunt, take the sure out'),
  ('general', 'defense', 3, 'Runners on first and second, nobody out. The batter bunts it hard right back to you on the mound.', 'Where do you throw?', array['First base for the sure out', 'Second base', 'Third base', 'Home plate'], 2, 'Both runners are forced, and a hard bunt gives you time to get the lead runner at third, where the shortstop is covering. On a slow bunt you''d take the out at first.', 3, '{"runners":["first","second"],"outs":0,"you":"P","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.37 · Runners at 1B & 2B, <2 outs: hard bunt to the pitcher'),
  ('general', 'defense', 3, 'Bases loaded, one out, infield playing in. Ground ball to you at shortstop.', 'Where do you throw?', array['Home to the catcher', 'First base for the sure out', 'Third base', 'Hold it and look the runners back'], 0, 'With the infield in and less than two outs, the job is to stop the run. Every runner is forced, so the catcher just touches home, and then she can look to first or third for a second out.', 3, '{"runners":["first","second","third"],"outs":1,"you":"SS","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Defensive Playbook p.49 · Bases loaded, <2 outs: ground ball with the infield in'),
  ('general', 'defense', 3, 'Bases loaded, one out. A fly ball to left field is caught and the runner on third tags up. The throw could go home or to third.', 'Who decides where the throw goes?', array['The left fielder', 'The shortstop, as the cut', 'The third baseman', 'The catcher'], 3, 'The catcher is facing the whole play and leads the communication. She makes the call, home or third, based on the score and how fast the runner on third is.', 3, '{"runners":["first","second","third"],"outs":1,"you":"C","ball":{"at":"LF","type":"fly"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.52 · Bases loaded, <2 outs: who calls the throw on a fly ball'),
  ('general', 'defense', 3, 'Runners on first and third, one out, infield playing in. Ground ball to you at shortstop, and the runner on third breaks for home.', 'Where do you throw?', array['First base for the sure out', 'Home to the catcher', 'Third base, behind the runner', 'Hold the ball and run at her'], 1, 'Always check the runner at third first. If she''s going, throw home to cut down the run; if she holds, look her back and take the out at first.', 3, '{"runners":["first","third"],"outs":1,"you":"SS","ball":{"at":"SS","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.57 · Runners at 1B & 3B, <2 outs: runner breaks home on a grounder'),
  ('general', 'defense', 3, 'Runners on second and third, one out. The runner on third breaks with the pitch and the batter squares to bunt: it''s a squeeze. The bunt comes to you at third base.', 'Where do you throw?', array['First base for the sure out', 'Third base', 'Home to the catcher', 'Hold the ball'], 2, 'On a squeeze the runner from third is already going, so field it and throw home, where the catcher has stayed to take the throw. Only take the out at first when the runner isn''t trying to score.', 3, '{"runners":["second","third"],"outs":1,"you":"3B","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.64 · Runners at 2B & 3B, <2 outs: squeeze bunt to third'),
  ('general', 'defense', 3, 'Runners on second and third, nobody out. The batter bunts a few feet in front of the plate, and the charging pitcher can get to it too. You''re the catcher.', 'What should you do?', array['Let the pitcher field it and stay home for a throw', 'Pounce on it yourself and throw to first', 'Run to cover third base', 'Back up first base'], 0, 'With a runner on third, home plate can''t be left empty. If another fielder can make the play, let her have it and stay at the plate so you can take a throw if the runner tries to score.', 3, '{"runners":["second","third"],"outs":0,"you":"C","ball":{"at":"bunt-C","type":"bunt"}}'::jsonb, 'Defensive Playbook p.63 · Runners at 2B & 3B, <2 outs: catcher on a bunt in front of the plate'),
  ('general', 'defense', 3, 'Runners on first and second, two outs. A hard ground ball is hit right at you at third base, near the bag.', 'What''s your play?', array['Step on third base', 'Throw to first', 'Tag the runner coming from second', 'Throw to second'], 0, 'The runner from second is forced to third, so on a hard ball right at you, just step on the bag for the third out; no tag needed. If the ball pulls you forward or is hit slowly, throw to first instead.', 3, '{"runners":["first","second"],"outs":2,"you":"3B","ball":{"at":"3B","type":"ground"}}'::jsonb, 'Defensive Playbook p.89 · Runners at 1B & 2B, 2 outs: hard grounder at third'),
  ('general', 'defense', 3, 'Bases loaded, two outs. The batter bunts it right in front of the plate and you pick it up. You''re the catcher.', 'Do you need to tag the runner coming home from third?', array['Yes, plays at the plate are always tag plays', 'No, just touch home plate with the ball', 'Only if she slides', 'Yes, the runner on third is never forced'], 1, 'With the bases loaded, every runner is forced, including the one coming home. Step on the plate with the ball for the third out; a throw to first works too.', 3, '{"runners":["first","second","third"],"outs":2,"you":"C","ball":{"at":"bunt-C","type":"bunt"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.92 · Bases loaded, 2 outs: force at home on a bunt'),
  ('general', 'defense', 3, 'Runners on first and third, two outs. A ground ball single goes into left field. You''re the pitcher.', 'Where do you go?', array['Back up home plate', 'Cover first base', 'Back up third base', 'Back up second base'], 2, 'The runner from third scores on a two-out single, so the left fielder throws through the shortstop cut to third to stop the runner coming from first. The pitcher backs up third in case that throw gets away.', 3, '{"runners":["first","third"],"outs":2,"you":"P","ball":{"at":"LF","type":"ground"}}'::jsonb, 'Defensive Playbook p.99 · Runners at 1B & 3B, 2 outs: pitcher''s backup on a single to left'),
  ('general', 'defense', 3, 'Runners on second and third, two outs. A ground ball gets past you into right field for a single. You''re the second baseman.', 'Once the ball is by you, where do you go?', array['Cover second base', 'Become the cut to home', 'Back up the right fielder', 'Fill in at first base'], 3, 'The first baseman usually becomes the cut to home on this play, which leaves first open. You fill in at first so there''s still a play on the batter-runner; the shortstop has second and the center fielder backs up right.', 3, '{"runners":["second","third"],"outs":2,"you":"2B","ball":{"at":"RF","type":"ground"}}'::jsonb, 'Defensive Playbook p.105 · Runners at 2B & 3B, 2 outs: filling in at first on a single to right'),
  ('general', 'baserunning', 1, 'Nobody on, no outs. You hit a routine ground ball to the shortstop.', 'How do you run it out?', array['Sprint hard straight through first base', 'Round first and look for second in case of a bad throw', 'Slide headfirst into first to beat the throw', 'Ease up and stop right on the bag so you don''t overrun it'], 0, 'On an infield grounder the only play is at first, so run through the bag at full speed and break down past it. Stopping on the base or sliding into it only slows you down.', 1, '{"runners":[],"outs":0,"you":"batter","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Baserunning Playbook p.3 · No runners, <2 outs: ground ball to SS'),
  ('general', 'baserunning', 1, 'Two outs, nobody on. You hit a clean single on the ground through the left side into left field.', 'What do you do at first base?', array['Run straight through first, like on an infield grounder', 'Make a hard turn at first and put pressure on the left fielder', 'Stop on first so you don''t take chances with two outs', 'Head straight for second no matter what'], 1, 'A hard, aggressive turn makes the left fielder hurry. If she bobbles it or lobs it back in, you''re already in position to take second; running straight through gives that chance away.', 1, '{"runners":[],"outs":2,"you":"batter","ball":{"at":"LF","type":"ground"}}'::jsonb, 'Baserunning Playbook p.16 · No runners, 2 outs: single to LF'),
  ('general', 'baserunning', 1, 'One out, you''re on first. The batter hits a ground ball to the third baseman.', 'What do you do?', array['Hold at first until you see where the throw goes', 'Run halfway to second and stop to avoid a double play', 'Run hard to second and slide', 'Run to second standing up and round the bag toward third'], 2, 'You''re forced to move on any ground ball, so get to second fast. Slide in, because the defense may go for the lead out at second.', 1, '{"runners":["first"],"outs":1,"you":"runner-first","ball":{"at":"3B","type":"ground"}}'::jsonb, 'Baserunning Playbook p.4 · Runner at 1B, <2 outs: ground ball to the infield'),
  ('general', 'baserunning', 1, 'No outs, you''re on second and the other bases are empty. The batter hits a ground ball to the shortstop.', 'What''s your move?', array['Run straight to third as soon as the ball is hit', 'Stay glued to second no matter where the throw goes', 'Head for third only after the batter is called safe at first', 'Get a good jump, then take third once she throws to first'], 3, 'A ball hit in front of you on the left side puts the shortstop in easy throwing range of third. Get off the bag ready to go, let her commit her throw to first, then take third. On a grounder to the right side you''d simply run.', 1, '{"runners":["second"],"outs":0,"you":"runner-second","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Baserunning Playbook p.5 · Runner at 2B, <2 outs: ground ball to SS'),
  ('general', 'baserunning', 1, 'One out, you''re on third. The batter hits a fly ball to medium-deep center field.', 'What do you do?', array['Go halfway down the line and wait to see if it''s caught', 'Run home as soon as the ball is hit', 'Tag up and sprint home the moment it''s caught', 'Stay on third so you don''t risk the run with one out'], 2, 'With fewer than two outs, a fly ball to the outfield is a tag-up. Get on the bag, leave on the catch, and score; the exception is a short fly that pulls the fielder way in.', 1, '{"runners":["third"],"outs":1,"you":"runner-third","ball":{"at":"CF","type":"fly"}}'::jsonb, 'Baserunning Playbook p.7 · Runner at 3B, <2 outs: fly ball to CF'),
  ('general', 'baserunning', 1, 'Two outs, you''re on third. The batter pops the ball up to the shortstop.', 'What do you do?', array['Run straight home as soon as it''s hit', 'Stay close to third in case she drops it', 'Tag up and go home on the catch', 'Go halfway home and read the catch'], 0, 'With two outs, a catch ends the inning, so there''s nothing to protect by staying. Run on contact; if she drops it, you''re already most of the way home.', 1, '{"runners":["third"],"outs":2,"you":"runner-third","ball":{"at":"SS","type":"popup"}}'::jsonb, 'Baserunning Playbook p.20 · Runner at 3B, 2 outs: pop-up to the infield'),
  ('general', 'baserunning', 1, 'Two outs, you''re on first. The batter hits a fly ball to center field.', 'What do you do?', array['Go halfway to second and wait to see if it''s caught', 'Tag up at first and go on the catch', 'Stay on first until the ball is caught or drops', 'Run on contact, round second, and be ready to take third if it''s dropped'], 3, 'With two outs, a catch ends the inning, so you run on contact. Rounding second puts you in position to take third if the center fielder drops it; going halfway is the play with fewer than two outs.', 1, '{"runners":["first"],"outs":2,"you":"runner-first","ball":{"at":"CF","type":"fly"}}'::jsonb, 'Baserunning Playbook p.17 · Runner at 1B, 2 outs: fly ball to CF'),
  ('general', 'baserunning', 1, 'One out, you''re on first. The batter hits a ground ball to the shortstop, who throws to the second baseman covering second.', 'What does the second baseman need to do to get you out?', array['Tag you with the ball before you reach the bag', 'Have the ball and touch second before you get there', 'Tag you and touch the bag at the same time', 'Catch the ball while standing anywhere near second'], 1, 'You''re forced to run because the batter is coming behind you, so it''s a force play: the fielder only needs the ball and a foot on the base before you arrive. A tag is needed when a runner isn''t forced.', 1, '{"runners":["first"],"outs":1,"you":"runner-first","ball":{"at":"SS","type":"ground"},"arrows":[{"from":"SS","to":"second","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.2 · Rules: force out vs. tag out'),
  ('general', 'baserunning', 1, 'No outs, you''re on first. You want a good lead without leaving early.', 'When do you start moving off the bag?', array['As soon as the pitcher steps onto the rubber', 'When the pitcher begins her windup', 'When her arm hits the peak of her pitching motion, so your foot comes off the base on the release', 'After the ball crosses home plate'], 2, 'Start moving at the peak of her motion so you come off the base right as she lets the ball go. Too early and you can be called for leaving early; too late and your lead is wasted.', 1, '{"runners":["first"],"outs":0,"you":"runner-first"}'::jsonb, 'Baserunning Playbook p.30 · Leads: timing off the bag'),
  ('general', 'baserunning', 1, 'No outs, you''re on first. The batter rips a line drive right at the shortstop.', 'What''s your first reaction?', array['Freeze, then react once you see if it''s caught or gets through', 'Run hard to second because you''re forced on a batted ball', 'Go halfway to second, like on a fly ball to the outfield', 'Take a big lead to try to draw a throw'], 0, 'A line drive is either caught or past the infielder in a split second. If you''re already running and it''s caught, you get doubled off, so freeze first and react to what happens.', 1, '{"runners":["first"],"outs":0,"you":"runner-first","ball":{"at":"SS","type":"line"}}'::jsonb, 'Baserunning Playbook p.29 · Line drive in the infield: freeze'),
  ('general', 'baserunning', 2, 'One out, you''re on second and the other bases are empty. The batter hits a fly ball to medium-deep right field.', 'What do you do?', array['Go halfway to third and wait for the catch', 'Tag up and take third once it''s caught', 'Stay on second, because you never tag from second', 'Run on contact and try to score'], 1, 'A fly to right is behind you and the throw from right field to third is a long one, so tag and go on the catch. On a fly to left, where the throw to third is short, you''d go partway and read it instead.', 2, '{"runners":["second"],"outs":1,"you":"runner-second","ball":{"at":"RF","type":"fly"}}'::jsonb, 'Baserunning Playbook p.6 · Runner at 2B, <2 outs: fly ball to RF'),
  ('general', 'baserunning', 2, 'Two outs, you''re on second. The batter hits a single on the ground into left field.', 'As you run to third, what decides whether you score?', array['Your own look back at the left fielder', 'Nothing; with two outs you always score from second on a single', 'Your first-base coach''s call', 'Your third-base coach, who tells you to slide, stay up on the bag, round it, or go home'], 3, 'Run hard to third and find your third-base coach; she sees the fielder, the throw, and the plate all at once. Follow her call instead of slowing down to look for the ball yourself.', 2, '{"runners":["second"],"outs":2,"you":"runner-second","ball":{"at":"LF","type":"ground"}}'::jsonb, 'Baserunning Playbook p.18 · Runner at 2B, 2 outs: single to LF (reading the 3B coach)'),
  ('general', 'baserunning', 2, 'Two outs, runners on first and third. You single into left field, and the left fielder throws to third trying to get the runner from first.', 'What do you do?', array['Take second on the throw to third', 'Stay on first, because you never advance on a throw to another base', 'Go to second only if the throw to third is wild', 'Run straight through first and walk back to the bag'], 0, 'Once the left fielder commits her throw to third, nobody is in position to stop you at second. Round first with your eyes on the ball and take the free base.', 2, '{"runners":["first","third"],"outs":2,"you":"batter","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"second","to":"third","kind":"run"},{"from":"LF","to":"third","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.25 · Runners at 1B & 3B, 2 outs: batter on a single to LF'),
  ('general', 'baserunning', 2, 'Two outs, runners on second and third. You''re on second, and the batter hits a ground ball to the shortstop, who is fielding it in your path to third.', 'What do you do?', array['Hold at second until she throws to first', 'Run straight through her path, since it''s her job to get out of your way', 'Run to third on contact, but go around her while she fields the ball', 'Freeze, because the ball is hit in front of you'], 2, 'With two outs you run on contact, but a fielder making a play on a batted ball has the right of way. Run into her and it''s interference, and you can be called out, so steer around her.', 2, '{"runners":["second","third"],"outs":2,"you":"runner-second","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Baserunning Playbook p.26 · Runners at 2B & 3B, 2 outs: ground ball to SS'),
  ('general', 'baserunning', 2, 'One out, you''re on third and the other bases are empty. The batter hits a ground ball right back to the pitcher.', 'What do you do?', array['Run home as soon as it''s hit', 'Freeze and stay close to third', 'Go halfway home and wait to see where she throws', 'Tag up on third, then run home'], 1, 'The pitcher fields it a few steps from the plate and is looking right at you, so breaking for home is an easy out. Hold third and let the batter take first.', 2, '{"runners":["third"],"outs":1,"you":"runner-third","ball":{"at":"P","type":"ground"}}'::jsonb, 'Baserunning Playbook p.7 · Runner at 3B, <2 outs: ground ball back to the pitcher'),
  ('general', 'baserunning', 2, 'One out, you''re on third. The batter hits a short fly ball that pulls the left fielder way in, and she''s set to catch it in shallow left.', 'What''s your best play?', array['Tag up and go home on the catch no matter what', 'Go halfway down the line and read it', 'Stay on the bag and don''t move after the catch', 'Tag up, then take a hard lead after the catch to try to draw a throw'], 3, 'A shallow catch leaves the fielder a short, strong throw home, so scoring is unlikely. Still tag, then break hard off the bag after the catch to bait a throw; a hurried or wild one can give you the run.', 2, '{"runners":["third"],"outs":1,"you":"runner-third","ball":{"at":"LF","type":"fly"}}'::jsonb, 'Baserunning Playbook p.29 · Runner at 3B, <2 outs: shallow fly (draw a throw)'),
  ('general', 'baserunning', 2, 'One out, you''re on third and the pitcher is about to deliver.', 'How should you take your lead?', array['Take a later lead, going off in foul territory and coming back in fair territory', 'Take a big, early lead in fair territory', 'Go off in fair territory and come back in foul territory', 'Don''t lead at all; stay on the bag until the ball is hit'], 0, 'A later lead at third keeps you from getting doubled off on a line drive. Coming back on the fair side of the line puts your body in the catcher''s throwing lane, which makes a pickoff throw harder.', 2, '{"runners":["third"],"outs":1,"you":"runner-third"}'::jsonb, 'Baserunning Playbook p.30 · Leads: taking a lead at third base'),
  ('general', 'baserunning', 2, 'One out, you''re on first, and you might get the steal sign this inning.', 'What should you watch to decide how you''ll slide into second?', array['How deep the outfielders are playing', 'Only how hard the pitcher throws', 'Who covers second, whether she gets there on time, and how accurate the catcher''s throws have been', 'Whether the batter is ahead or behind in the count'], 2, 'Knowing who covers, whether she''s early or late, and where the catcher''s throws have been going tells you where the tag will come from. That''s how you decide to slide straight in or to one side of the bag.', 2, '{"runners":["first"],"outs":1,"you":"runner-first"}'::jsonb, 'Baserunning Playbook p.31 · Steal tips: scouting before you steal second'),
  ('general', 'baserunning', 2, 'One out, you''re on second. The batter pops a ball up foul behind home plate toward the third-base side, and the catcher and third baseman both chase it.', 'What do you do?', array['Run to third on contact, since a foul ball doesn''t count', 'Tag up at second and watch whether third base is left uncovered', 'Go halfway to third and wait', 'Stay off the bag, because a foul ball is always dead'], 1, 'A caught foul pop is a live ball you can tag up on. With two fielders chasing it and nobody covering third, a good tag can turn into a free base after the catch.', 2, '{"runners":["second"],"outs":1,"you":"runner-second","ball":{"at":"popup-C","type":"popup"}}'::jsonb, 'Baserunning Playbook p.29 · Foul pop-up: tag up'),
  ('general', 'baserunning', 2, 'One out, nobody on. You hit a ball into the left-center gap.', 'Gap hits usually mean thinking two bases. Which of these is a good reason to hold at first?', array['There''s already one out', 'It went to left-center instead of right-center', 'It''s early in the game', 'It was hit so hard that it reached the outfielder almost instantly'], 3, 'The standard plays assume normal conditions. A rocket that gets to the outfielder fast, a slower runner, or a great defensive play can take away the extra base, so adjust instead of running into an out.', 2, '{"runners":[],"outs":1,"you":"batter","ball":{"at":"LCF-gap","type":"line"}}'::jsonb, 'Baserunning Playbook p.1 · Gap hit: when you can''t push for two'),
  ('general', 'baserunning', 3, 'One out, runners on first and third. Your coach calls the 75% steal, and you''re the runner on first. As you head for second, the catcher throws all the way through to second.', 'What do you do?', array['Kick into full speed and slide into second', 'Turn and sprint straight back to first', 'Stop, get into a rundown, and stay alive so the runner on third can score', 'Stop where you are and let them tag you to avoid a collision'], 2, 'On the 75% play you take second only if they give it to you. If they throw through, get caught in a rundown and keep it going; every throw gives the runner on third a chance to score.', 3, '{"runners":["first","third"],"outs":1,"you":"runner-first","arrows":[{"from":"first","to":"second","kind":"steal"},{"from":"C","to":"second","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.31 · First & third: 75% steal, catcher throws through'),
  ('general', 'baserunning', 3, 'One out, you''re on first and the other bases are empty. Your coach puts on the delayed steal.', 'When do you take off for second?', array['On the catcher''s return throw to the pitcher', 'On the pitcher''s release, like a straight steal', 'When the pitcher starts her windup', 'After the pitcher gets the ball back and steps on the rubber'], 0, 'A delayed steal counts on the defense relaxing after the pitch: take your normal lead, then go as the catcher tosses it back to the circle. Scout it first: does the catcher look you back, does the pitcher glance your way, and which way does she turn as she catches the return?', 3, '{"runners":["first"],"outs":1,"you":"runner-first"}'::jsonb, 'Baserunning Playbook p.31 · Delayed steal: when to go'),
  ('general', 'baserunning', 3, 'No outs, runners on first and third. You''re on third, and the runner on first takes off for second on the pitch.', 'When do you break for home?', array['As soon as the catcher catches the pitch', 'As soon as the catcher stands up to throw', 'Never; stay on third no matter what', 'Only once you see the throw is going all the way through to second'], 3, 'If you leave early, a fake, a short throw, or a cut-off can trap you between third and home. Read the throw, and only go once the ball is clearly headed through to second.', 3, '{"runners":["first","third"],"outs":0,"you":"runner-third","arrows":[{"from":"first","to":"second","kind":"steal"}]}'::jsonb, 'Baserunning Playbook p.31 · First & third: runner at 3B on a steal of second'),
  ('general', 'baserunning', 3, 'Bases loaded, one out. You''re on third, and the batter hits a ground ball to the shortstop.', 'What do you do?', array['Freeze unless the infield is playing back', 'Sprint home and slide', 'Hold until the defense throws to first, then go', 'Go back and tag third before running'], 1, 'With the bases loaded you''re forced, so the usual reads at third don''t apply; you have to go. Run hard and slide, because the defense may come home for the force.', 3, '{"runners":["first","second","third"],"outs":1,"you":"runner-third","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Baserunning Playbook p.10 · Bases loaded, <2 outs: ground ball (runner at 3B)'),
  ('general', 'baserunning', 3, 'No outs, runners on second and third. You''re on second. The batter hits a ground ball to the shortstop, and the runner on third holds.', 'What do you do?', array['Run to third, because you''re forced on a ground ball', 'Run to third so the lead runner has to go home', 'Hold at second, because the runner ahead of you didn''t go', 'Get into a rundown to help the runner on third score'], 2, 'You''re the trail runner and you aren''t forced, so you can only take third after the runner in front of you leaves it. Get a good jump, but if she stays, you stay.', 3, '{"runners":["second","third"],"outs":0,"you":"runner-second","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Baserunning Playbook p.14 · Runners at 2B & 3B, <2 outs: ground ball to SS (trail runner)'),
  ('general', 'baserunning', 3, 'Two outs, runners on first and second. You''re on second and you''re one of the fastest players on the team. The batter bunts, and the pitcher fields it and throws to first.', 'What do you do?', array['Round third hard and be ready to score if the first baseman drops the throw', 'Stop on third and stay there', 'Score no matter what happens at first', 'Go back to second in case of a double play'], 0, 'The defense is going for the third out at first. If you''ve already rounded third, you can score when the first baseman drops it; if she catches it, the inning is over anyway and the run wouldn''t count.', 3, '{"runners":["first","second"],"outs":2,"you":"runner-second","ball":{"at":"bunt-P","type":"bunt"},"arrows":[{"from":"P","to":"first","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.21 · Runners at 1B & 2B, 2 outs: bunt with the play at first'),
  ('general', 'baserunning', 3, 'One out, runners on first and second. The batter pops up to the shortstop, the umpire calls infield fly, and the shortstop drops it. You''re on second.', 'What do you have to do?', array['Run to third, because once the ball hits the ground you''re forced', 'Run to third, because the batter is now safe at first and pushes you along', 'Go to third, because a dropped infield fly awards every runner a base', 'Nothing; the batter is already out, so you''re not forced and can stay at second'], 3, 'Once infield fly is called, the batter is out whether the ball is caught or not, which takes away the force. You can stay where you are and only advance if you can take the base safely.', 3, '{"runners":["first","second"],"outs":1,"you":"runner-second","ball":{"at":"SS","type":"popup"}}'::jsonb, 'Baserunning Playbook p.9 · Infield fly rule: ball dropped'),
  ('general', 'baserunning', 3, 'One out, you''re on second. The batter hits a ball into the left-center gap. As you run to third, the third baseman, who doesn''t have the ball and isn''t fielding it, steps into your path and you have to swerve around her.', 'What is this called?', array['Interference, and you''re out', 'Obstruction on the defense', 'Nothing, because fielders can stand wherever they want', 'Running out of the baseline, and you''re out'], 1, 'Obstruction is a fielder without the ball, and not making a play, getting in a runner''s way. Interference is the reverse: the runner blocking or running into a fielder who is making a play. Keep running hard and let the umpire make the call.', 3, '{"runners":["second"],"outs":1,"you":"runner-second","ball":{"at":"LCF-gap","type":"line"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Baserunning Playbook p.2 · Rules: obstruction'),
  ('general', 'baserunning', 3, 'Bases loaded, two outs. You''re on first, and the batter pops up to the second baseman.', 'What do you do?', array['Run straight to second on contact', 'Stay near first, because the infield fly rule protects you', 'Tag up at first and go on the catch', 'Go halfway to second and read it'], 0, 'The infield fly rule only applies with fewer than two outs. With two outs a catch ends the inning, so everyone runs on contact; if it''s dropped, you need to beat the force at second.', 3, '{"runners":["first","second","third"],"outs":2,"you":"runner-first","ball":{"at":"2B","type":"popup"}}'::jsonb, 'Baserunning Playbook p.24 · Bases loaded, 2 outs: pop-up to the infield'),
  ('general', 'baserunning', 3, 'One out, runners on first and third. No squeeze is on, but the batter bunts toward first base. You''re on third.', 'What''s your read?', array['Break for home the moment the ball is bunted, like a squeeze', 'Stay on third no matter what, since no squeeze means no run', 'Read the fielder and break for home when she throws to first', 'Go back and tag third before you run'], 2, 'On a squeeze you''re already running on the pitch, but without one you have to read the play. When the fielder commits her throw to first, that''s your window to score; if the bunt is popped up, freeze and get back.', 3, '{"runners":["first","third"],"outs":1,"you":"runner-third","ball":{"at":"bunt-1B","type":"bunt"}}'::jsonb, 'Baserunning Playbook p.12 · Runners at 1B & 3B, <2 outs: bunt with no squeeze on');
